DELETE FROM assessment_question WHERE quiz_id IN (@onyomi_quiz_1_1, @onyomi_quiz_1_2, @onyomi_quiz_1_3, @onyomi_quiz_1_4, @onyomi_quiz_1_5, @onyomi_quiz_1_6, @onyomi_quiz_1_7, @onyomi_quiz_1_8, @onyomi_quiz_1_9, @onyomi_quiz_1_10, @onyomi_quiz_2_1, @onyomi_quiz_2_2, @onyomi_quiz_2_3, @onyomi_quiz_2_4, @onyomi_quiz_3_1, @onyomi_quiz_3_2, @onyomi_quiz_3_3, @onyomi_quiz_3_4, @onyomi_quiz_3_5)
