INSERT INTO conversion_rule (lesson_id, source_sound, target_sound, title, description,
                             example_breakdown, tip, note, display_order) VALUES
    (@onyomi_lesson_1_1, 'C', 'K', 'Âm đầu C → K', 'Âm đầu C (không phải CH) thường tương ứng với hàng カ (K) trong âm On.', 'Công (工) → コウ (kou)', 'Nghe “Công”, nghĩ ngay tới “コ…”: 工 コウ, 高 コウ, 各 カク.', 'C đứng trước I/Ê/Y trong Hán Việt được viết là K; hai quy tắc này thực chất là một.', 1),
    (@onyomi_lesson_1_1, 'K', 'K', 'Âm đầu K → K', 'Âm đầu K thường giữ hàng カ (K); đôi khi hữu thanh hoá thành ガ (G).', 'Kim (金) → キン (kin)', 'K của Hán Việt gần như luôn là K của âm On: 金 キン, 期 キ, 見 ケン.', '技 (Kỹ) đọc ギ: K hữu thanh hoá thành G.', 2),
    (@onyomi_lesson_1_1, 'QU', 'K', 'Âm đầu QU → K', 'Âm đầu QU thường tương ứng với hàng カ (K); một số chữ hữu thanh thành ガ (G).', 'Quốc (国) → コク (koku)', 'Bỏ âm “u” lướt của QU: Quốc → コク, Quan → カン.', '軍 (Quân) đọc グン: QU hữu thanh hoá thành G.', 3),
    (@onyomi_lesson_1_2, 'H', 'K/G', 'Âm đầu H → K/G', 'Âm đầu H trong Hán Việt thường tương ứng với hàng カ (K) hoặc ガ (G), không phải ハ.', 'Học (学) → ガク (gaku)', 'Bẫy hay gặp: 海 (Hải) đọc カイ chứ không phải ハイ.', 'Một số chữ mất hẳn phụ âm, ví dụ 和 (Hòa) → ワ.', 1),
    (@onyomi_lesson_1_2, 'NG', 'G', 'Âm đầu NG → G', 'Âm đầu NG/NGH thường tương ứng với hàng ガ (G).', 'Ngũ (五) → ゴ (go)', 'Ngũ → ゴ, Ngân → ギン, Ngữ → ゴ: NG mất âm mũi, còn lại G.', NULL, 2),
    (@onyomi_lesson_1_3, 'L', 'R', 'Âm đầu L → R', 'Âm đầu L luôn tương ứng với hàng ラ (R) vì tiếng Nhật không có âm L.', 'Lợi (利) → リ (ri)', 'L → R là quy tắc ổn định nhất: 利 リ, 料 リョウ, 練 レン.', NULL, 1),
    (@onyomi_lesson_1_3, 'N', 'N', 'Âm đầu N → N', 'Âm đầu N thường giữ hàng ナ (N).', 'Nam (南) → ナン (nan)', 'Nam → ナン, Niên → ネン, Năng → ノウ.', '内 (Nội) còn có âm ダイ trong 境内.', 2),
    (@onyomi_lesson_1_3, 'NH', 'N/J', 'Âm đầu NH → N/J', 'Âm đầu NH thường tương ứng với ニ/ニュ (N) hoặc ジ (J).', 'Nhị (二) → ニ (ni)', 'Nhân → ジン hoặc ニン, Nhật → ニチ hoặc ジツ: thử cả N lẫn J.', '然 (Nhiên) đọc ゼン: NH có thể thành Z.', 3),
    (@onyomi_lesson_1_4, 'S', 'S/SH', 'Âm đầu S → S/SH', 'Âm đầu S thường giữ hàng サ (S hoặc SH).', 'Sinh (生) → セイ (sei)', 'Sinh → セイ, Sơn → サン, Sở → ショ.', NULL, 1),
    (@onyomi_lesson_1_4, 'T', 'S', 'Âm đầu T → S', 'Âm đầu T (không phải TH, TR) thường tương ứng với hàng サ (S/SH), không phải タ.', 'Tiên (先) → セン (sen)', 'Bẫy hay gặp: 先 (Tiên) đọc セン chứ không phải テン.', NULL, 2),
    (@onyomi_lesson_1_4, 'X', 'SH', 'Âm đầu X → SH', 'Âm đầu X thường tương ứng với シャ/シュ/ショ (SH).', 'Xa (車) → シャ (sha)', 'Xa → シャ, Xuân → シュン, Xuất → シュツ.', '赤 (Xích) đọc セキ: X cũng có thể thành S.', 3),
    (@onyomi_lesson_1_5, 'TH', 'S/T', 'Âm đầu TH → S/T', 'Âm đầu TH thường tương ứng với hàng サ (S/SH) hoặc タ (T/TS).', 'Thất (失) → シツ (shitsu)', 'Thất → シツ, Thế → セイ nhưng Thiên → テン, Thông → ツウ.', NULL, 1),
    (@onyomi_lesson_1_5, 'TR', 'CH/T', 'Âm đầu TR → CH/T', 'Âm đầu TR thường tương ứng với チ/チャ/チュ/チョ (CH), đôi khi タ (T/TS).', 'Trường (長) → チョウ (chou)', 'Trường → チョウ, Trung → チュウ, Truy → ツイ.', NULL, 2),
    (@onyomi_lesson_1_6, 'KH', 'K', 'Âm đầu KH → K', 'Âm đầu KH thường tương ứng với hàng カ (K).', 'Khai (開) → カイ (kai)', 'Khai → カイ, Không → クウ, Khách → キャク.', NULL, 1),
    (@onyomi_lesson_1_6, 'GI', 'K/G', 'Âm đầu GI → K/G', 'Âm đầu GI thường tương ứng với hàng カ (K), đôi khi ガ (G).', 'Gia (家) → カ (ka)', 'Gia → カ, Gian → カン, Giáo → キョウ.', NULL, 2),
    (@onyomi_lesson_1_7, 'B', 'H/B', 'Âm đầu B → H/B', 'Âm đầu B thường tương ứng với hàng ハ (H), đôi khi giữ バ (B).', 'Bắc (北) → ホク (hoku)', 'Bản → ホン, Bán → ハン, nhưng Bệnh → ビョウ.', NULL, 1),
    (@onyomi_lesson_1_7, 'PH', 'H', 'Âm đầu PH → H', 'Âm đầu PH thường tương ứng với hàng ハ (H, kể cả フ).', 'Phương (方) → ホウ (hou)', 'Phương/Pháp/Phóng → ホウ, Phụ → フ, Phi → ヒ.', 'Trong từ ghép, ハ hay biến thành パ/バ: 文法 ぶんぽう.', 2),
    (@onyomi_lesson_1_8, 'M', 'M/B', 'Âm đầu M → M/B', 'Âm đầu M thường tương ứng với hàng マ (M) hoặc バ (B).', 'Môn (門) → モン (mon)', 'Môn → モン, Minh → メイ, nhưng Mã → バ, Mẫu → ボ.', NULL, 1),
    (@onyomi_lesson_1_8, 'V', 'B/M/–', 'Âm đầu V → B/M hoặc mất phụ âm', 'Âm đầu V thường tương ứng với バ (B), マ (M), hoặc mất hẳn phụ âm đầu.', 'Văn (文) → ブン (bun)', 'Văn → ブン, Vấn → モン, Viên → エン, Vương → オウ.', NULL, 2),
    (@onyomi_lesson_1_9, 'Đ', 'T/D', 'Âm đầu Đ → T/D', 'Âm đầu Đ thường tương ứng với hàng タ (T) hoặc ダ (D).', 'Đại (大) → ダイ (dai)', 'Đông → トウ, Đại → ダイ, Điện → デン.', NULL, 1),
    (@onyomi_lesson_1_9, 'D', 'Y', 'Âm đầu D → Y', 'Âm đầu D (không phải Đ) thường tương ứng với hàng ヤ (Y).', 'Dược (薬) → ヤク (yaku)', 'Bẫy hay gặp: D không thành ダ hay ザ. Dược → ヤク, Dụng → ヨウ.', '以 (Dĩ) đọc イ: phụ âm mất hẳn.', 2),
    (@onyomi_lesson_1_10, 'CH', 'S/SH', 'Âm đầu CH → S/SH', 'Âm đầu CH thường tương ứng với hàng サ (S/SH), không phải チ.', 'Chính (正) → セイ (sei)', 'Bẫy hay gặp: Chính → セイ, Chủ → シュ (không phải チ…).', '準 (Chuẩn) đọc ジュン: CH hữu thanh hoá thành J.', 1),
    (@onyomi_lesson_1_10, '(nguyên âm)', 'nguyên âm/Y', 'Nguyên âm đầu → nguyên âm/Y', 'Chữ Hán Việt bắt đầu bằng nguyên âm (A, Â, Ư, Ô, Y…) thường giữ nguyên âm ở âm On, hoặc thêm Y.', 'An (安) → アン (an)', 'An → アン, Ý → イ, Ước → ヤク, Ưu → ユウ.', NULL, 2),
    (@onyomi_lesson_2_1, 'M', 'ン', 'Âm cuối M → ン', 'Âm cuối -M của Hán Việt thành ン (n) trong âm On.', 'Tam (三) → サン (san)', 'Tam → サン, Tâm → シン, Kim → キン: -m và -n đều thành ン.', NULL, 1),
    (@onyomi_lesson_2_1, 'N', 'ン', 'Âm cuối N → ン', 'Âm cuối -N của Hán Việt giữ nguyên thành ン.', 'Văn (文) → ブン (bun)', 'Văn → ブン, Sơn → サン, Bản → ホン.', NULL, 2),
    (@onyomi_lesson_2_2, 'C', 'ク', 'Âm cuối C → ク', 'Âm cuối -C của Hán Việt thường thành ク (ku) ở cuối âm On.', 'Ác (悪) → アク (aku)', 'Quốc → コク, Học → ガク, Lực → リョク.', 'Một số chữ thành キ hoặc ツ, ví dụ 式 (Thức) → シキ, 実 (Thực) → ジツ.', 1),
    (@onyomi_lesson_2_3, 'CH', 'キ/ク', 'Âm cuối CH → キ/ク', 'Âm cuối -CH thành キ (ki) sau I/Ê (-ICH, -ÊCH), và thành ク (ku) sau A (-ACH).', 'Lịch (歴) → レキ (reki)', 'Lịch → レキ, Tịch → セキ; nhưng Bạch → ハク, Khách → キャク.', NULL, 1),
    (@onyomi_lesson_2_4, 'T', 'ツ/チ', 'Âm cuối T → ツ/チ', 'Âm cuối -T của Hán Việt thành ツ (tsu), đôi khi チ (chi).', 'Thiết (鉄) → テツ (tetsu)', 'Thiết → テツ, Quyết → ケツ; Nhật → ニチ, Bát → ハチ.', NULL, 1),
    (@onyomi_lesson_2_4, 'P', 'ウ', 'Âm cuối P → ウ (trường âm)', 'Âm cuối -P của Hán Việt thường biến thành trường âm ウ: -ap/-ơp → オウ, -âp/-ip → ュウ.', 'Thập (十) → ジュウ (juu)', 'Thập → ジュウ, Cấp → キュウ, Pháp → ホウ, Hợp → ゴウ.', 'Một số chữ giữ dấu vết -p thành ツ, ví dụ 接 (Tiếp) → セツ, 圧 (Áp) → アツ.', 2),
    (@onyomi_lesson_3_1, 'AN', 'AN', 'Vần AN → アン', 'Vần AN (kể cả OAN) thường giữ nguyên thành アン.', 'An (安) → アン (an)', 'An → アン, Gian → カン, Hoàn → カン.', NULL, 1),
    (@onyomi_lesson_3_1, 'AM', 'AN', 'Vần AM → アン', 'Vần AM cũng thành アン (âm cuối -M thành ン).', 'Tam (三) → サン (san)', 'Tam → サン, Cảm → カン, Nam → ナン.', NULL, 2),
    (@onyomi_lesson_3_2, 'ÂN', 'IN', 'Vần ÂN → イン', 'Vần ÂN thường thành イン.', 'Ấn (印) → イン (in)', 'Tân → シン, Cận → キン, Dân → ミン.', NULL, 1),
    (@onyomi_lesson_3_2, 'ÂM', 'IN', 'Vần ÂM → イン', 'Vần ÂM thường thành イン (âm cuối -M thành ン).', 'Tâm (心) → シン (shin)', 'Tâm → シン, Lâm → リン, Cấm → キン.', '音 (Âm) thường đọc オン (音楽); イン chỉ gặp trong vài từ như 母音.', 2),
    (@onyomi_lesson_3_3, 'IÊN', 'EN', 'Vần IÊN → エン', 'Vần IÊN (kể cả UYÊN) thường thành エン.', 'Viên (円) → エン (en)', 'Thiên → テン, Tiên → セン, Nguyên → ゲン.', NULL, 1),
    (@onyomi_lesson_3_3, 'IÊM', 'EN', 'Vần IÊM → エン', 'Vần IÊM thường thành エン (âm cuối -M thành ン).', 'Điếm (店) → テン (ten)', 'Điểm → テン, Kiểm → ケン, Niệm → ネン.', NULL, 2),
    (@onyomi_lesson_3_4, 'ANG', 'OU', 'Vần ANG → オウ', 'Vần ANG (kể cả OANG) thường thành trường âm オウ.', 'Quang (光) → コウ (kou)', 'Quang → コウ, Cảng → コウ, Đảng → トウ.', NULL, 1),
    (@onyomi_lesson_3_4, 'ƯƠNG', 'OU', 'Vần ƯƠNG → オウ', 'Vần ƯƠNG thường thành trường âm オウ, hay đi với âm ghép (ョウ).', 'Trường (長) → チョウ (chou)', 'Trường → チョウ, Chương → ショウ, Phương → ホウ.', NULL, 2),
    (@onyomi_lesson_3_4, 'ÔNG', 'OU/UU', 'Vần ÔNG → オウ/ウウ', 'Vần ÔNG thường thành オウ, đôi khi ウウ.', 'Công (工) → コウ (kou)', 'Công → コウ, Đông → トウ, nhưng Thông → ツウ, Không → クウ.', NULL, 3),
    (@onyomi_lesson_3_5, 'ANH', 'EI', 'Vần ANH → エイ', 'Vần ANH (kể cả OANH) thường thành エイ.', 'Thanh (青) → セイ (sei)', 'Thanh → セイ, Anh → エイ, Cảnh → ケイ.', '行 (Hành) đọc コウ/ギョウ: ANH thành オウ.', 1),
    (@onyomi_lesson_3_5, 'ÊNH', 'EI', 'Vần ÊNH → エイ', 'Vần ÊNH thường thành エイ. Vần này ít chữ, nên gặp là nhớ luôn.', 'Mệnh (命) → メイ (mei)', 'Mệnh → メイ, Lệnh → レイ.', '病 (Bệnh) đọc ビョウ: ÊNH thành ョウ.', 2),
    (@onyomi_lesson_3_5, 'INH', 'EI', 'Vần INH → エイ', 'Vần INH thường thành エイ.', 'Sinh (生) → セイ (sei)', 'Sinh → セイ, Định → テイ, Minh → メイ.', NULL, 3)
ON DUPLICATE KEY UPDATE source_sound = VALUES(source_sound), target_sound = VALUES(target_sound),
    title = VALUES(title), description = VALUES(description), example_breakdown = VALUES(example_breakdown),
    tip = VALUES(tip), note = VALUES(note);
SET @onyomi_rule_init_c = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_1 AND display_order = 1);
SET @onyomi_rule_init_k = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_1 AND display_order = 2);
SET @onyomi_rule_init_qu = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_1 AND display_order = 3);
SET @onyomi_rule_init_h = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_2 AND display_order = 1);
SET @onyomi_rule_init_ng = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_2 AND display_order = 2);
SET @onyomi_rule_init_l = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_3 AND display_order = 1);
SET @onyomi_rule_init_n = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_3 AND display_order = 2);
SET @onyomi_rule_init_nh = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_3 AND display_order = 3);
SET @onyomi_rule_init_s = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_4 AND display_order = 1);
SET @onyomi_rule_init_t = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_4 AND display_order = 2);
SET @onyomi_rule_init_x = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_4 AND display_order = 3);
SET @onyomi_rule_init_th = (SELECT id FROM conversion_rule WHERE lesson_id = @onyomi_lesson_1_5 AND display_order = 1);
